// index.ts
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";

const server = new Server(
  { name: "my-server", version: "1.0.0" },
  { capabilities: { tools: {} } }
);

server.setRequestHandler("tools/list", async () => ({
  tools: [{
    name: "greet",
    description: "Generate a greeting",
    inputSchema: {
      type: "object",
      properties: { name: { type: "string" } },
      required: ["name"]
    }
  }]
}));

server.setRequestHandler("tools/call", async (req) => {
  if (req.params.name === "greet") {
    return {
      content: [{ type: "text", text: `Hello, ${req.params.arguments.name}!` }]
    };
  }
  throw new Error("Unknown tool");
});

const transport = new StdioServerTransport();
await server.connect(transport);

// internal-api-server.ts
server.setRequestHandler("tools/call", async (req) => {
  if (req.params.name === "query_internal_db") {
    const response = await fetch("https://internal.api/query", {
      method: "POST",
      headers: { "Authorization": `Bearer ${process.env.API_TOKEN}` },
      body: JSON.stringify(req.params.arguments)
    });
    return { content: [{ type: "text", text: await response.text() }] };
  }
});

